def reachable(graph: dict[str, list[str]], start: str) -> set[str]:
    seen = {start}
    queue = deque([start])
    while queue:
        node = queue.popleft()
        for dep in graph.get(node, ()):
            if dep not in seen:
                seen.add(dep)
                queue.append(dep)
    return seen

