        return Decimal(self.percent) / 100


REGISTRY: dict[str, Discount] = {
    "WELCOME10": PercentDiscount(10),
    "VIP20": PercentDiscount(20),
    "STAFF50": PercentDiscount(50),
}


def apply_discount(total: Decimal, code: str | None) -> Decimal:
    discount = REGISTRY.get(code or "")
    rate = discount.rate() if discount else Decimal(0)
    return (total * (1 - rate)).quantize(Decimal("0.01"))

